CREATE TABLE IF NOT EXISTS professionals (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,professional_code VARCHAR(40) NOT NULL UNIQUE,license_number VARCHAR(80) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_prof_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS professional_specialties (professional_id BIGINT NOT NULL,specialty_id SMALLINT NOT NULL,is_primary BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(professional_id,specialty_id),CONSTRAINT fk_ps_prof FOREIGN KEY(professional_id) REFERENCES professionals(id),CONSTRAINT fk_ps_spec FOREIGN KEY(specialty_id) REFERENCES specialties(id));
CREATE TABLE IF NOT EXISTS professional_locations (professional_id BIGINT NOT NULL,location_id SMALLINT NOT NULL,PRIMARY KEY(professional_id,location_id),CONSTRAINT fk_pl_prof FOREIGN KEY(professional_id) REFERENCES professionals(id),CONSTRAINT fk_pl_loc FOREIGN KEY(location_id) REFERENCES locations(id));
